/// Cipher tests: cross-language vectors generated by the reference Python
/// implementation (mobile/tool/make_vectors.py) plus rule-specific tests.
///
/// Run with: flutter test
/// These MUST pass before any release — they are what guarantees keys
/// interoperate between the app and the Python translator.
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:copiale_translator/copiale/cipher.dart';
import 'package:copiale_translator/copiale/errors.dart';
import 'package:copiale_translator/copiale/locked.dart';

late Map<String, dynamic> vectors;

void main() {
  setUpAll(() {
    final raw =
        File('test/test_vectors.json').readAsStringSync(encoding: utf8);
    vectors = json.decode(raw) as Map<String, dynamic>;
  });

  group('derivation tag', () {
    test('matches reference', () {
      expect(vectors['derivation'], lockedDerivation);
      expect(vectors['alphabet'], lockedAlphabet);
    });
  });

  group('permutations match Python exactly', () {
    test('all vectors', () {
      for (final v in vectors['permutations'] as List) {
        expect(lockedPermutation(v['key'] as String), v['permutation'],
            reason: "key ${v['key']}");
      }
    });
  });

  group('locked round-trips match Python exactly', () {
    test('tokens identical', () {
      for (final v in vectors['locked'] as List) {
        final toks =
            encode(v['plaintext'] as String, key: v['key'] as String).tokens;
        expect(toks, List<String>.from(v['tokens'] as List),
            reason: "locked encode ${v['plaintext']}");
        expect(decode(toks, key: v['key'] as String).text, v['decoded'],
            reason: "locked decode ${v['plaintext']}");
      }
    });
  });

  group('unkeyed samples match Python exactly', () {
    test('tokens and text identical', () {
      for (final v in vectors['plain'] as List) {
        final res = encode(v['plaintext'] as String);
        expect(res.tokens, List<String>.from(v['tokens'] as List),
            reason: "encode ${v['plaintext']}");
        expect(decode(res.tokens).text, v['decoded'],
            reason: "decode ${v['plaintext']}");
      }
    });
  });

  group('key behaviour', () {
    test('wrong key and no key give gibberish, right key restores', () {
      const text = 'meet at midnight';
      const key = 'my-secret-key';
      final toks = encode(text, key: key).tokens;
      expect(decode(toks, key: key).text, text);
      expect(decode(toks).text, isNot(text));
      expect(decode(toks, key: 'wrong-key').text, isNot(text));
    });

    test('strict rejects keys', () {
      expect(() => encode('hi', mode: 'strict', key: 'k'),
          throwsA(isA<CopialeError>()));
      expect(() => decode(['hd'], mode: 'strict', key: 'k'),
          throwsA(isA<CopialeError>()));
    });

    test('empty key rejected', () {
      expect(() => encode('hi', key: '  '), throwsA(isA<CopialeError>()));
      expect(() => decode(['hd'], key: ''), throwsA(isA<CopialeError>()));
    });

    test('keygen format', () {
      final k = generateKey(12);
      expect(k.length, 12);
      expect(RegExp(r'^[A-Za-z0-9]+$').hasMatch(k), isTrue);
      expect(generateKey(), isNot(generateKey()));
    });

    test('unknown token: strict throws, experimental flags', () {
      expect(() => decode(['qqx'], mode: 'strict'),
          throwsA(isA<CopialeError>()));
      final r = decode(['qqx']);
      expect(r.unknown, ['qqx']);
      expect(r.text.contains('qqx'), isTrue);
    });

    test('colon repeat', () {
      expect(decode(['lam', ':']).text, 'tt');
    });

    test('logogram markers survive locked decode', () {
      expect(decode(['star'], key: 'k').text, '*star*');
    });
  });
}
